/// <summary>
/// Service class for sales picking list generation service
/// </summary>
class METSalesPickingListGenerationService extends SysOperationServiceBase
{
    METSalesPickingListGenerationContract   dataContract;
    //Batch                                   batchTask;
    //Batch                                   batchTaskCurrent;
    BatchHeader                             batchHeader;

}

Method.Source:
    /// <summary>
    /// processing logic
    /// </summary>
    /// <param name = "_dataContract">The data contract</param>
    public void process(METSalesPickingListGenerationContract _dataContract)
    {
        dataContract = _dataContract;

        this.initialise();
        this.processTasks();
    }

/// <summary>Initialise global variables</summary>
public void initialise()
{
    if (dataContract && dataContract.parmBatchJobId())
    {
        batchHeader         = BatchHeader::construct(dataContract.parmBatchJobId());
    }
    else
    {
        batchHeader         = BatchHeader::construct();
    }
          
}

    /// <summary>Create sub tasks that do the actual calculations</summary>
    public void processTasks()
    {        
        int i;
        METSalesPickingListGenerationTaskController         salesPickingListGenerationTaskController, salesPickingListGenerationTaskControllerFinal;
        METSalesPickingListGenerationTaskContract           salesPickingListGenerationTaskContract;
        Set                                                 transactionTasks;
        container                                           conShipmentIds, salesContainer;  
        MetShipmentId                                       metShipmentId;
        List                                                salesPickingListGenerationTaskControllerList;
        SalesId                                             salesId, salesIdLocal;
        METCustParameters                                   metCustParameters = METCustParameters::Find();
        //CB123 - SalesOrderExtractScreenforCSD - start
        utcdatetime curDateTime = DateTimeUtil::getSystemDateTime();
        //CB123 - SalesOrderExtractScreenforCSD - end

        transactionTasks = new Set(Types::Class);
        salesPickingListGenerationTaskControllerList = new List(Types::Class);

        ttsbegin;

        salesContainer = dataContract.parmSalesOrderList();

        for (i = 1; i <= conLen(salesContainer); i++)
        {
            salesIdLocal = conPeek(salesContainer, i);

            if (SalesTable::find(salesIdLocal).CredManInCreditControl)
            {
                warning(strFmt("@MET:SOCredMgmtValidation", salesIdLocal));
                continue;
            }
            salesPickingListGenerationTaskController = METSalesPickingListGenerationTaskController::construct(); 
            
           
            salesPickingListGenerationTaskContract = this.buildDataContract(salesPickingListGenerationTaskController, 
                                                                            conPeek(salesContainer, i));
            // Call guide check for this specific sales order
            //this.performSOGuideCheckloc(salesPickingListGenerationTaskContract.parmSalesId());

            //Create shipment header and loads to prevent the batch task dead lock issue.
            METOrderShipmentLoadCreation        shipmentLoadCreation = METOrderShipmentLoadCreation::construct(METOrderTransactionType::SalesOrder, 
                                                                                                                    salesPickingListGenerationTaskContract.parmSalesId());
            metShipmentId = shipmentLoadCreation.createShippmentLoad(true,true);

            if (conFind(conShipmentIds, metShipmentId) == 0)
            {
                conShipmentIds += [metShipmentId];
            }

            //CB123 - SalesOrderExtractScreenforCSD - start
            this.updateSalesOrderExtractDateTime(salesPickingListGenerationTaskContract,
                                                 dataContract.parmCSDSalesOrderList(),
                                                 salesPickingListGenerationTaskContract.parmSalesId(),
                                                 curDateTime);
            
            salesPickingListGenerationTaskContract.parmCSDSalesOrderCount(conLen(dataContract.parmCSDSalesOrderList()));
            salesPickingListGenerationTaskContract.parmCSDSalesOrderExtractDateTime(curDateTime);            
            salesPickingListGenerationTaskContract.parmContinueFromStagingLane(dataContract.parmContinueFromStagingLane());

            if (dataContract.parmCsdGuid() && conLen(dataContract.parmCSDSalesOrderList()) > 0)
            {
                salesPickingListGenerationTaskContract.parmCsdGuid(dataContract.parmCsdGuid());
                salesId = salesPickingListGenerationTaskContract.parmSalesId();
            }

            // Add to list for dependency tracking
            salesPickingListGenerationTaskControllerList.addEnd(salesPickingListGenerationTaskController);
            
            //CB123 - SalesOrderExtractScreenforCSD - end
            batchHeader.addTask(salesPickingListGenerationTaskController);
            //CB395_CSDFulfilementInterBranchTransfer - start
            transactionTasks.add(salesPickingListGenerationTaskController);
            //CB395_CSDFulfilementInterBranchTransfer - end

        }

        if (salesPickingListGenerationTaskControllerList.elements() == 0)
        {
            ttsabort;
            return;
        }
        salesPickingListGenerationTaskController = METSalesPickingListGenerationTaskController::construct();
           
        salesPickingListGenerationTaskContract = salesPickingListGenerationTaskController.getDataContractObject();
        salesPickingListGenerationTaskContract.parmTriggerBusinessEvent(true);

        if (salesId)
        {
            salesPickingListGenerationTaskContract.parmCSDSalesId(salesId);
            salesPickingListGenerationTaskContract.parmCSDSalesOrderList(dataContract.parmCSDSalesOrderList());
            salesPickingListGenerationTaskContract.parmCsdGuid(dataContract.parmCsdGuid());
            salesPickingListGenerationTaskContract.parmCSDSalesOrderExtractDateTime(curDateTime);
        }
        

        //There is chance to have blank shipment header created above and because of any failure in picking list generation task, the shipment lines will not be created.
        //In such case need to check if blank shipment header can be deleted in last thread of task.
        salesPickingListGenerationTaskContract.parmShipmentIdList(conShipmentIds);

        salesPickingListGenerationTaskControllerFinal = salesPickingListGenerationTaskController;

        batchHeader.addTask(salesPickingListGenerationTaskController);
        //CB395_CSDFulfilementInterBranchTransfer - start
        transactionTasks.add(salesPickingListGenerationTaskController);

        ttscommit;

        // Add dependency so that finalisation task runs at the end
        ListEnumerator enumerator = salesPickingListGenerationTaskControllerList.getEnumerator();
        while (enumerator.moveNext())
        {
            salesPickingListGenerationTaskController =  enumerator.current();
            batchHeader.addDependency(salesPickingListGenerationTaskControllerFinal, salesPickingListGenerationTaskController);
        }
        
        //CB395_CSDFulfilementInterBranchTransfer - start
        if (conLen(dataContract.parmCSDSalesOrderList()) > 0)
        {
            this.addCreateCSDTransferOrderTask(dataContract.parmCSDSalesOrderList(), transactionTasks);
        }
        //CB395_CSDFulfilementInterBranchTransfer - end

        if (dataContract.parmBatchJobId() == 0)
        {
            batchHeader.parmCaption(strFmt("@MET:ExtractServiceBy", "@MET:MetPickingListGeneration", curUserId()));
        }

        if (metCustParameters.SalesExtractionBatchGroupId)
        {
            batchHeader.parmBatchGroup(metCustParameters.SalesExtractionBatchGroupId);
        }

        batchHeader.save();
    }

/// <summary>
/// To check if this SO has the guide check reason codes 
/// </summary>
/// <param name = "_salesId">_salesId</param>
public void performSOGuideCheckloc(SalesId _salesId)
{
    SalesLine salesLine;
    METSalesLine metSalesLine;
    SalesTable salesTable;
    // Run for all records that are backordered and have the reason codes.
    while select salesLine
        where salesLine.SalesId == _salesId
            &&  salesLine.SalesStatus == SalesStatus::Backorder
        join ReasonId from metSalesLine
            where metSalesLine.SalesLine == salesLine.RecId
        exists join salesTable
            where salesTable.SalesId ==  salesLine.SalesId
            && (salesTable.METOrderExtractStatus == METOrderExtractStatus::Open
                || salesTable.METOrderExtractStatus == METOrderExtractStatus::ReadyForExtract)
    {
        METSalesOrderGuideCheckTaskService METSalesOrderGuideCheckTaskService = new METSalesOrderGuideCheckTaskService();
        METSalesOrderGuideCheckTaskService.performSOGuideCheck(salesLine);
    }
}

/// <summary>
/// contract METSalesPickingListGenerationTaskContract
/// </summary>
/// <param name = "_taskController">METSalesPickingListGenerationTaskController</param>
/// <param name = "_salesOrderList">sales order list</param>
/// <returns>METSalesPickingListGenerationTaskContract</returns>
public METSalesPickingListGenerationTaskContract buildDataContract(METSalesPickingListGenerationTaskController _taskController, container _salesOrderList)
{
    METSalesPickingListGenerationTaskContract   salesPickingListGenerationTaskContract;
    
    salesPickingListGenerationTaskContract = _taskController.getDataContractObject();
    salesPickingListGenerationTaskContract.parmSalesId(conPeek(_salesOrderList, 1));
    salesPickingListGenerationTaskContract.parmContinueFromStagingLane(dataContract.parmContinueFromStagingLane());
    
    return salesPickingListGenerationTaskContract;
}

    /// <summary>
    /// CB123 - SalesOrderExtractScreenforCSD
    /// Update Sales order extract date time
    /// </summary>
    /// <param name = "_salesPickingListGenerationTaskContract">METSalesPickingListGenerationTaskContract</param>
    /// <param name = "_csdSalesOrderList">csd sales order list</param>
    /// <param name = "_salesId">sales id</param>
    /// <param name = "_extractedDateTime">extracted date time</param>
    private void updateSalesOrderExtractDateTime(METSalesPickingListGenerationTaskContract _salesPickingListGenerationTaskContract,
                                                 container _csdSalesOrderList, 
                                                 SalesId _salesId, 
                                                 utcdatetime _extractedDateTime)
    {
        #OCCRetryCount

        try
        {
            int position = conFind(_csdSalesOrderList, _salesId);

            if (position > 0)
            {
                _salesPickingListGenerationTaskContract.parmCSDSalesId(conPeek(_csdSalesOrderList, position));
                SalesTable salesTable = SalesTable::find(_salesId, true);

                if (salesTable)
                {
                    //update the extract date and time
                    salesTable.skipDataMethods(true);
                    salesTable.METOrderExtractDateTime = _extractedDateTime;
                    salesTable.update();
                }
            }
        }
        catch (Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Error)
        {
            throw error("@SYS93835");
        }
    }

    /// <summary>
    /// CB395_CSDFulfilementInterBranchTransfer.
    /// Adds <c>METCreateCSDTransferOrderController</c> as the final task.
    /// It is dependent on successful execution of tasks scheduled before it.
    /// </summary>
    /// <param name = "_csdSalesIdList">CSD Sales ID List.</param>
    /// <param name = "_transactionTasks">Transaction tasks.</param>
    private void addCreateCSDTransferOrderTask(container _csdSalesIdList, Set _transactionTasks)
    {
        SysOperationServiceController controller =  METCreateCSDTransferOrderController::construct(_csdSalesIdList);
        METCreateCSDTransferOrderContract contract = controller.getDataContractObject() as METCreateCSDTransferOrderContract;
        contract.parmContinueFromStagingLane(dataContract.parmContinueFromStagingLane());
        
        SetEnumerator transactionTasksEnumerator = _transactionTasks.getEnumerator() as SetEnumerator;

        batchHeader.addTask(controller);

        while (transactionTasksEnumerator && transactionTasksEnumerator.moveNext())
        {
            SysOperationServiceController transactionTaskController = transactionTasksEnumerator.current();
            batchHeader.addDependency(controller, transactionTaskController, BatchDependencyStatus::Finished);
        }
    }
